  theta_se: number | null;
  bench: BenchReading | null;
  verify: VerifyReading | null;
  theta_caveat: 'cold_ruler' | 'flat_ruler' | 'collapsed_band' | 'prior_pinned' | 'unmeasured_delta' | 'floor_pinned' | null;
